arguments.command:
curl -s -X POST https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: Bearer <TOKEN>' -d '{"query":"{ projects(first: 100) { nodes { id name identifier } } users(first: 100) { nodes { id name email } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for p in d['data']['projects']['nodes']:
    print('PROJECT', p['id'], p.get('identifier'), p['name'])
print('---')
for u in d['data']['users']['nodes']:
    if 'maya' in (u['name'] or '').lower() or 'chen' in (u['name'] or '').lower():
        print('USER', u['id'], u['name'], u.get('email'))
"

